package com.fintaxpro;
import java.math.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.stream.*;
/** Exact integer-paise ledger; BigDecimal is used at numeric and percentage boundaries. */
public final class Finance {
 public record Profile(String name,String business,long minimum){}
 public record Account(String id,String name,long opening,String asOf){}
 public record Tx(String id,String accountId,String description,long amount,String direction,String scope,String category,String date,String method,String commitmentId,String occurrence,String reference,String importKey,String importReferenceKey,String importBatchId){
 public Tx(String id,String accountId,String description,long amount,String direction,String scope,String category,String date,String method,String commitmentId,String occurrence){this(id,accountId,description,amount,direction,scope,category,date,method,commitmentId,occurrence,null,null,null,null);}}
 public record ImportBatch(String id,String fileName,String createdAt,String accountId,int imported,int duplicatesSkipped){}
 public record Commitment(String id,String accountId,String description,long amount,String direction,String scope,String category,String date,String frequency,String priority){}
 public record Pot(String id,String accountId,String name,long target,long balance,double percentage){}
 public record Allocation(String id,String potId,long amount,String kind,String date){}
 public record State(Profile profile,List<Account> accounts,List<Tx> transactions,List<Commitment> commitments,List<Pot> pots,List<Allocation> allocations,List<Map<String,Object>> runs,List<Map<String,Object>> taxEstimates,List<String> dismissed,List<ImportBatch> importHistory){
 public State(Profile profile,List<Account> accounts,List<Tx> transactions,List<Commitment> commitments,List<Pot> pots,List<Allocation> allocations,List<Map<String,Object>> runs,List<Map<String,Object>> taxEstimates,List<String> dismissed){this(profile,accounts,transactions,commitments,pots,allocations,runs,taxEstimates,dismissed,new ArrayList<>());}}
 public record Event(Commitment schedule,String occurrence,String due){}
 public static LocalDate today(){return LocalDate.now(ZoneId.of("Asia/Kolkata"));}
 public static State empty(String name){return new State(new Profile(name,"Independent professional",1000000),new ArrayList<>(),new ArrayList<>(),new ArrayList<>(),new ArrayList<>(),new ArrayList<>(),new ArrayList<>(),new ArrayList<>(),new ArrayList<>());}
 public static State copy(State s){return new State(s.profile,new ArrayList<>(s.accounts),new ArrayList<>(s.transactions),new ArrayList<>(s.commitments),new ArrayList<>(s.pots),new ArrayList<>(s.allocations),new ArrayList<>(s.runs),new ArrayList<>(s.taxEstimates),new ArrayList<>(s.dismissed),new ArrayList<>(s.importHistory==null?List.of():s.importHistory));}
 public static long amount(Object o,boolean zero){try{long v=new BigDecimal(String.valueOf(o)).longValueExact();if(v<(zero?0:1)||v>100000000000L)throw new IllegalArgumentException();return v;}catch(Exception e){throw new IllegalArgumentException("Enter a valid amount in integer paise.");}}
 static String str(Map<String,Object>d,String key){Object v=d.get(key);if(!(v instanceof String s)||s.isBlank()||s.length()>180)throw new IllegalArgumentException("Complete the required fields.");return s.trim();}
 static String opt(Map<String,Object>d,String key,String... opts){String v=str(d,key);if(!List.of(opts).contains(v))throw new IllegalArgumentException("Invalid "+key);return v;}
 static String date(Map<String,Object>d,String key){try{return LocalDate.parse(str(d,key)).toString();}catch(Exception e){throw new IllegalArgumentException("Invalid date.");}}
 static String id(){return UUID.randomUUID().toString();}
 static String account(State s,Map<String,Object>d){String a=str(d,"accountId");if(s.accounts.stream().noneMatch(x->x.id.equals(a)))throw new IllegalArgumentException("Account not found.");return a;}
 public static long accountBalance(State s,String a){return s.accounts.stream().filter(x->x.id.equals(a)).mapToLong(Account::opening).sum()+s.transactions.stream().filter(t->t.accountId.equals(a)&&t.date.compareTo(today().toString())<=0).mapToLong(t->t.direction.equals("INCOME")?t.amount:-t.amount).sum();}
 public static long balance(State s){return s.accounts.stream().mapToLong(a->accountBalance(s,a.id)).sum();}
 public static long reserved(State s){return s.pots.stream().mapToLong(Pot::balance).sum();}
 static void checkReserves(State s){for(Account a:s.accounts){long r=s.pots.stream().filter(p->p.accountId.equals(a.id)).mapToLong(Pot::balance).sum();if(r>Math.max(0,accountBalance(s,a.id)))throw new IllegalArgumentException("Release affected reserves before reducing account funds.");}}
 public static List<Event> events(State s,LocalDate until){List<Event> out=new ArrayList<>();for(Commitment c:s.commitments){LocalDate base=LocalDate.parse(c.date),d=base;for(int i=0;i<1000&&!d.isAfter(until);i++){String occurrence=d.toString();if(s.transactions.stream().noneMatch(t->c.id.equals(t.commitmentId)&&occurrence.equals(t.occurrence)))out.add(new Event(c,occurrence,d.isBefore(today())?today().toString():occurrence));if(c.frequency.equals("NONE"))break;d=c.frequency.equals("WEEKLY")?d.plusWeeks(1):base.plusMonths(i+1);}}return out.stream().sorted(Comparator.comparing(Event::due)).toList();}
 public static List<Map<String,Object>> forecast(State s,int days,int delay,int reduction,long release){long b=balance(s),reserve=reserved(s)-Math.min(reserved(s),Math.max(0,release));List<Event> events=events(s,today().plusDays(days));List<Map<String,Object>> out=new ArrayList<>();for(int i=0;i<=days;i++){LocalDate d=today().plusDays(i);long income=0,expense=0;List<String> names=new ArrayList<>();for(Event e:events){Commitment c=e.schedule;LocalDate due=LocalDate.parse(e.due).plusDays(c.direction.equals("INCOME")?delay:0);if(due.equals(d)){names.add(c.description);if(c.direction.equals("INCOME"))income+=c.amount;else expense+=c.priority.equals("FLEXIBLE")?BigDecimal.valueOf(c.amount).multiply(BigDecimal.valueOf(100-reduction)).divide(BigDecimal.valueOf(100),0,RoundingMode.HALF_UP).longValueExact():c.amount;}}b+=income-expense;Map<String,Object> p=new LinkedHashMap<>();p.put("date",d.toString());p.put("label",d.format(DateTimeFormatter.ofPattern("d MMM",Locale.ENGLISH)));p.put("balance",b);p.put("available",b-reserve);p.put("income",income);p.put("expense",expense);p.put("minimum",s.profile.minimum);p.put("events",names);out.add(p);}return out;}
 public static Map<String,Object> tax(long income,long deductions,String regime){amount(income,true);amount(deductions,true);if(income>500000000L)throw new IllegalArgumentException("Calculator supports ordinary income up to ₹50 lakh.");boolean n=regime.equals("NEW");if(!n&&!regime.equals("OLD"))throw new IllegalArgumentException("Invalid regime.");long taxable=Math.max(0,income-(n?0:deductions))/1000*1000;long[] bounds=n?new long[]{0,40000000,80000000,120000000,160000000,200000000,240000000,Long.MAX_VALUE}:new long[]{0,25000000,50000000,100000000,Long.MAX_VALUE};int[] rates=n?new int[]{0,5,10,15,20,25,30}:new int[]{0,5,20,30};List<Map<String,Object>> rows=new ArrayList<>();long base=0;for(int i=0;i<rates.length;i++){long portion=Math.max(0,Math.min(taxable,bounds[i+1])-bounds[i]);long part=BigDecimal.valueOf(portion).multiply(BigDecimal.valueOf(rates[i])).divide(BigDecimal.valueOf(100),0,RoundingMode.HALF_UP).longValueExact();base+=part;Map<String,Object> row=new LinkedHashMap<>();row.put("from",bounds[i]);row.put("to",bounds[i+1]==Long.MAX_VALUE?null:bounds[i+1]);row.put("rate",rates[i]);row.put("tax",part);rows.add(row);}long rebate=n?(taxable<=120000000?Math.min(base,6000000):0):(taxable<=50000000?Math.min(base,1250000):0),relief=n&&taxable>120000000?Math.max(0,base-(taxable-120000000)):0,after=Math.max(0,base-rebate-relief);long cess=BigDecimal.valueOf(after).multiply(new BigDecimal("0.04")).setScale(0,RoundingMode.HALF_UP).longValueExact(),total=BigDecimal.valueOf(after+cess).divide(BigDecimal.valueOf(1000),0,RoundingMode.HALF_UP).longValueExact()*1000;Map<String,Object> r=new LinkedHashMap<>();r.put("income",income);r.put("deductions",n?0:deductions);r.put("taxable",taxable);r.put("rows",rows);r.put("base",base);r.put("rebate",rebate);r.put("relief",relief);r.put("cess",cess);r.put("total",total);r.put("regime",regime);r.put("year","AY 2026–27");r.put("version","india-ay2026-27-v1");return r;}
 public static State apply(State old,String type,Map<String,Object>d){State s=copy(old);String now=today().toString();switch(type){
 case "profile","initialize"->{return new State(new Profile(str(d,"name"),str(d,"business"),amount(d.get("minimum"),true)),s.accounts,s.transactions,s.commitments,s.pots,s.allocations,s.runs,s.taxEstimates,s.dismissed,s.importHistory);}
 case "account"->{if(s.accounts.size()>=20)throw new IllegalArgumentException("Maximum 20 accounts.");String asOf=date(d,"asOf");if(asOf.compareTo(now)>0)throw new IllegalArgumentException("Opening date cannot be in the future.");s.accounts.add(new Account(id(),str(d,"name"),amount(d.get("opening"),true),asOf));}
 case "transaction"->{String a=account(s,d),dt=date(d,"date");if(dt.compareTo(now)>0||dt.compareTo(s.accounts.stream().filter(x->x.id.equals(a)).findFirst().orElseThrow().asOf)<0)throw new IllegalArgumentException("Transaction date is outside the account's valid period.");Tx previous=d.containsKey("id")?s.transactions.stream().filter(t->t.id.equals(d.get("id"))).findFirst().orElseThrow(()->new IllegalArgumentException("Transaction not found.")):null;if(s.transactions.size()>=5000&&previous==null)throw new IllegalArgumentException("Maximum 5,000 transactions.");Tx t=new Tx(previous==null?id():previous.id,a,str(d,"description"),amount(d.get("amount"),false),opt(d,"direction","INCOME","EXPENSE"),opt(d,"scope","BUSINESS","PERSONAL"),str(d,"category"),dt,String.valueOf(d.getOrDefault("method","Other")),previous==null?null:previous.commitmentId,previous==null?null:previous.occurrence,previous==null?null:previous.reference,previous==null?null:previous.importKey,previous==null?null:previous.importReferenceKey,previous==null?null:previous.importBatchId);s.transactions.remove(previous);s.transactions.add(0,t);checkReserves(s);}
 case "deleteTransaction"->{if(!s.transactions.removeIf(t->t.id.equals(d.get("id"))))throw new IllegalArgumentException("Transaction not found.");checkReserves(s);}
 case "commitment"->{String dt=date(d,"date");if(LocalDate.parse(dt).isBefore(today().minusDays(365)))throw new IllegalArgumentException("Start a schedule within the past year.");String cid=d.containsKey("id")?str(d,"id"):id();if(d.containsKey("id")&&s.commitments.stream().noneMatch(c->c.id.equals(cid)))throw new IllegalArgumentException("Schedule not found.");if(s.commitments.size()>=500&&!d.containsKey("id"))throw new IllegalArgumentException("Maximum 500 schedules.");Commitment c=new Commitment(cid,account(s,d),str(d,"description"),amount(d.get("amount"),false),opt(d,"direction","INCOME","EXPENSE"),opt(d,"scope","BUSINESS","PERSONAL"),str(d,"category"),dt,opt(d,"frequency","NONE","MONTHLY","WEEKLY"),opt(d,"priority","ESSENTIAL","OBLIGATION","FLEXIBLE"));s.commitments.removeIf(x->x.id.equals(cid));s.commitments.add(c);}
 case "deleteCommitment"->s.commitments.removeIf(c->c.id.equals(d.get("id")));
 case "settle"->{Event e=events(s,today().plusDays(90)).stream().filter(x->x.schedule.id.equals(d.get("id"))&&x.occurrence.equals(d.get("occurrence"))).findFirst().orElseThrow(()->new IllegalArgumentException("Occurrence already settled or unavailable."));Commitment c=e.schedule;s.transactions.add(0,new Tx(id(),c.accountId,c.description,c.amount,c.direction,c.scope,c.category,now,"Other",c.id,e.occurrence));checkReserves(s);}
 case "pot"->{if(s.pots.size()>=30)throw new IllegalArgumentException("Maximum 30 reserve pots.");s.pots.add(new Pot(id(),account(s,d),str(d,"name"),amount(d.get("target"),false),0,Math.min(100,Math.max(0,Double.parseDouble(String.valueOf(d.getOrDefault("percentage",0)))))));}
 case "allocate","release"->{int index=-1;for(int i=0;i<s.pots.size();i++)if(s.pots.get(i).id.equals(d.get("id")))index=i;if(index<0)throw new IllegalArgumentException("Reserve not found.");Pot p=s.pots.get(index);long a=amount(d.get("amount"),false),next=p.balance+(type.equals("allocate")?a:-a);if(next<0)throw new IllegalArgumentException("Cannot release more than the reserved amount.");s.pots.set(index,new Pot(p.id,p.accountId,p.name,p.target,next,p.percentage));checkReserves(s);s.allocations.add(0,new Allocation(id(),p.id,a,type.equals("allocate")?"ALLOCATE":"RELEASE",Instant.now().toString()));}
 case "saveForecast"->{int days=((Number)d.get("days")).intValue();if(!List.of(7,14,30).contains(days))throw new IllegalArgumentException("Choose 7, 14 or 30 days.");Map<String,Object> r=new LinkedHashMap<>();r.put("id",id());r.put("days",days);r.put("createdAt",Instant.now().toString());r.put("startingBalance",balance(s));r.put("reserved",reserved(s));r.put("minimum",s.profile.minimum);r.put("assumptions","Scheduled cash flows; overdue items today; end-of-day balances; no unscheduled predictions.");r.put("events",events(s,today().plusDays(days)));r.put("points",forecast(s,days,0,0,0));s.runs.add(0,r);if(s.runs.size()>20)s.runs.remove(s.runs.size()-1);}
 case "saveTax"->{Map<String,Object> r=tax(amount(d.get("income"),true),amount(d.get("deductions"),true),opt(d,"regime","NEW","OLD"));r.put("id",id());r.put("createdAt",Instant.now().toString());s.taxEstimates.add(0,r);if(s.taxEstimates.size()>30)s.taxEstimates.remove(s.taxEstimates.size()-1);}
 case "importStatement"->{return StatementImports.apply(s,d);}
 case "dismiss"->s.dismissed.add(str(d,"id"));
 default->throw new IllegalArgumentException("Unsupported command.");}return s;}
}
